"""Regression coverage for declaration contexts in Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('truthy', [False, True])
def test_faker_decider_defaults(truthy):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'pybool', locale='en_US', truth_probability=100 if truthy else 0,
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == ('yes' if truthy else 'no')


def test_faker_decider_unrolls_context_and_keeps_branch_overrides_separate():
    class ExampleFactory(factory.DictFactory):
        probability = 100
        value = factory.Maybe(
            factory.Faker(
                'pybool', truth_probability=factory.SelfAttribute('..probability'),
            ),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration='no',
        )

    assert ExampleFactory(value__min_value=7, value__max_value=7)['value'] == 7
    assert ExampleFactory(probability=0)['value'] == 'no'


def test_decider_with_custom_pre_evaluation():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Transformer(False, transform=lambda value: not value),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == 'yes'
