    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pybool',
                truth_probability=factory.LazyFunction(lambda: 100 if value else 0),
                locale='en_US',
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

